/*!
 * \file
 * \brief Defines the compiled Sm-153 marginal source-emission laws.
 *
 * LNHB retained evaluations select independent emissions per parent decay.
 * Prompt photon and conversion yields are included where separable;
 * unsupported Auger energy laws, neutrinos and recoil are excluded.
 *
 * BetaShape 2.4 (06/2024): retained experimental factors where available,
 * otherwise calculated shapes. Integrated conditional masses are separate
 * from absolute yields. Forbidden non-unique calculated laws retain the
 * reported Xi-approximation limitations.
 *
 * Selection and exclusions: validation/radioactivity/data/Sm-153/reference/.
 *
 * \author Julien BERT <julien.bert@univ-brest.fr>
 * \author Didier BENOIT <didier.benoit@inserm.fr>
 */

